synthetic_events_2 AS (SELECT column1::NUMBER AS person_id, column2::DATE AS clinical_effective_date, column3::NUMBER AS mrc_grade FROM VALUES (-9732,'2026-08-01',3), (-9733,'2026-08-01',3), (-9734,'2026-08-01',3), (-9735,'2026-08-01',3), (-9736,'2026-08-01',3), (-9737,'2026-08-01',3), (-9738,'2026-08-01',3), (-9739,'2026-08-01',3), (-9741,'2026-08-01',3), (-9731,'2025-06-30',3), (-9740,'2026-10-01',3), (-9732,'2026-09-01',2)),
synthetic_events_3 AS (SELECT column1::NUMBER AS person_id, column2::DATE AS clinical_effective_date, column3::VARCHAR AS pr_obs_type FROM VALUES (-9731,'2025-07-01','Pulmonary Rehab Offered'), (-9734,'2026-07-31','Pulmonary Rehab Attended'), (-9735,'2026-08-01','Pulmonary Rehab Unsuitable'), (-9739,'2026-08-01','Pulmonary Rehab Attended'), (-9732,'2026-08-02','Pulmonary Rehab Declined'), (-9732,'2026-08-02','Pulmonary Rehab Declined'), (-9737,'2026-07-31','Pulmonary Rehab Declined'), (-9741,'2026-08-01','Pulmonary Rehab Declined')),
actual AS (SELECT person_id, reporting_date, is_in_numerator FROM ({{ query }})),
expected AS (SELECT column1::NUMBER AS person_id, column2::DATE AS reporting_date, column3::BOOLEAN AS is_in_numerator FROM VALUES (-9731,'2026-08-31',TRUE), (-9732,'2026-08-31',TRUE), (-9732,'2026-09-30',TRUE), (-9733,'2026-08-31',FALSE), (-9733,'2026-09-30',TRUE), (-9737,'2026-08-31',FALSE), (-9737,'2026-09-30',FALSE), (-9738,'2026-09-30',FALSE), (-9739,'2026-08-31',TRUE), (-9739,'2026-09-30',TRUE), (-9741,'2026-09-30',TRUE)),
actual_counts AS (SELECT *, COUNT(*) AS occurrences FROM actual GROUP BY ALL),
expected_counts AS (SELECT *, COUNT(*) AS occurrences FROM expected GROUP BY ALL),
failures AS ((SELECT * FROM actual_counts EXCEPT SELECT * FROM expected_counts) UNION ALL (SELECT * FROM expected_counts EXCEPT SELECT * FROM actual_counts))
SELECT COUNT(*) AS failure_count FROM failures HAVING COUNT(*) > 0
